import { test } from "node:test";
import assert from "node:assert/strict";
import { ingest, type StoredReading } from "../src/telemetry/ingest.ts";
import { hourlyAverages } from "../src/telemetry/stats.ts";

const now = () => new Date("2026-11-19T08:30:00Z");

function setup() {
    const rows: StoredReading[] = [];
    const store = { append: async (r: StoredReading[]) => void rows.push(...r) };
    return { rows, post: (body: unknown) => ingest(body, store, now) };
}

const reading = (sensor: string, value: unknown, at = "2026-11-19T08:10:00Z") => ({ sensor, value, at });
const details = (res: { body: unknown }) => (res.body as { details: string[] }).details;

test("a valid batch is accepted and stored with normalized timestamps", async () => {
    const { rows, post } = setup();
    const res = await post({ deviceId: "gh-north-07", readings: [reading("temp_c", 21.5, "2026-11-19T09:10:00+01:00"), reading("co2_ppm", 830)] });
    assert.deepEqual(res, { status: 202, body: { accepted: 2 } });
    assert.deepEqual(rows[0], { deviceId: "gh-north-07", sensor: "temp_c", value: 21.5, at: "2026-11-19T08:10:00.000Z" });
});

test("a value sent as a string is rejected", async () => {
    const { rows, post } = setup();
    const res = await post({ deviceId: "gh-north-07", readings: [reading("humidity_pct", 61), reading("temp_c", "21.5")] });
    console.log("response to a quoted temperature:", res, "stored:", rows);
    assert.equal(res.status, 400);
    assert.deepEqual(details(res), ["readings[1].value must be a number"]);
    assert.equal(rows.length, 0);
});

test("null, empty, boolean and missing values are rejected", async () => {
    const { post } = setup();
    const res = await post({
        deviceId: "gh-north-07",
        readings: [reading("temp_c", null), reading("temp_c", ""), reading("temp_c", true), { sensor: "temp_c", at: "2026-11-19T08:10:00Z" }],
    });
    assert.equal(res.status, 400);
    assert.equal(details(res).length, 4);
});

test("out-of-range values, unknown sensors and bad device ids are rejected", async () => {
    const { post } = setup();
    const res = await post({ deviceId: "GH North", readings: [reading("humidity_pct", 140), reading("lux", 300), reading("toString", 1)] });
    assert.equal(res.status, 400);
    assert.deepEqual(details(res), [
        "deviceId must be 3-40 lowercase letters, digits or dashes",
        "readings[0].value 140 is outside 0..100",
        "readings[1].sensor must be one of temp_c, humidity_pct, co2_ppm, soil_moisture_pct",
        "readings[2].sensor must be one of temp_c, humidity_pct, co2_ppm, soil_moisture_pct",
    ]);
});

test("timestamps must parse and be neither in the future nor over a week old", async () => {
    const { post } = setup();
    const res = await post({
        deviceId: "gh-south-01",
        readings: [reading("temp_c", 20, "yesterday"), reading("temp_c", 20, "2026-11-19T08:40:00Z"), reading("temp_c", 20, "2026-11-10T08:00:00Z"), reading("temp_c", 20, "2026-11-19T08:34:00Z")],
    });
    assert.deepEqual(details(res), ["readings[0].at must be an ISO timestamp", "readings[1].at is in the future", "readings[2].at is more than 7 days old"]);
    assert.equal((await post({ deviceId: "gh-south-01", readings: [] })).status, 400);
});

test("the dashboard's hourly averages stay correct when one firmware sends quoted or null values", async () => {
    const { rows, post } = setup();
    await post({ deviceId: "gh-east-02", readings: [reading("temp_c", 20), reading("temp_c", 22, "2026-11-19T08:20:00Z")] });
    await post({ deviceId: "gh-east-02", readings: [reading("temp_c", "23", "2026-11-19T08:25:00Z")] });
    await post({ deviceId: "gh-east-02", readings: [reading("temp_c", null, "2026-11-19T08:26:00Z")] });
    assert.deepEqual(hourlyAverages(rows, "gh-east-02"), [{ hour: "2026-11-19T08:00Z", sensor: "temp_c", average: 21, count: 2 }]);
});

test("averages are bucketed by hour and sensor", async () => {
    const { rows, post } = setup();
    await post({
        deviceId: "gh-east-02",
        readings: [reading("co2_ppm", 800, "2026-11-19T07:05:00Z"), reading("co2_ppm", 900, "2026-11-19T07:55:00Z"), reading("co2_ppm", 1000), reading("soil_moisture_pct", 35.25)],
    });
    assert.deepEqual(hourlyAverages(rows, "gh-east-02").map((a) => [a.hour, a.sensor, a.average, a.count]), [
        ["2026-11-19T07:00Z", "co2_ppm", 850, 2],
        ["2026-11-19T08:00Z", "co2_ppm", 1000, 1],
        ["2026-11-19T08:00Z", "soil_moisture_pct", 35.3, 1],
    ]);
});
